diff --git a/src/compiler/checker.ts b/src/compiler/checker.ts
index cd1409b13..bd9deedd1 100644
--- a/src/compiler/checker.ts
+++ b/src/compiler/checker.ts
@@ -8682,7 +8682,7 @@ export function createTypeChecker(host: TypeCheckerHost): TypeChecker {
             let result;
             const addUndefinedForParameter = declaration && (isParameter(declaration) || isJSDocParameterTag(declaration)) && requiresAddingImplicitUndefined(declaration, context.enclosingDeclaration);
             const decl = declaration ?? symbol.valueDeclaration ?? getDeclarationWithTypeAnnotation(symbol) ?? symbol.declarations?.[0];
-            if (!couldUnfoldType(type, context) && decl) {
+            if (!couldUnfoldType(type, context) && decl && isTypeOfDeclarationSymbol(decl, symbol, type)) {
                 if (isAccessor(decl)) {
                     result = syntacticNodeBuilder.serializeTypeOfAccessor(decl, symbol, context);
                 }
@@ -8705,6 +8705,21 @@ export function createTypeChecker(host: TypeCheckerHost): TypeChecker {
             return result ?? factory.createKeywordTypeNode(SyntaxKind.AnyKeyword);
         }
 
+        /**
+         * Syntax taken from a declaration (such as the type in a type assertion in its initializer) can only describe the type of that
+         * declaration's own symbol. Symbols derived from it (e.g. instantiated, mapped, spread or union/intersection property symbols)
+         * share its declarations but can have a different type, so the syntax may only be used for them if their type turned out the same
+         * (ignoring `undefined`, which is added or removed by optionality and is accounted for when reusing type annotations).
+         */
+        function isTypeOfDeclarationSymbol(declaration: Declaration, symbol: Symbol, type: Type) {
+            const declarationSymbol = getSymbolOfDeclaration(declaration);
+            if (!declarationSymbol || getMergedSymbol(symbol) === declarationSymbol) {
+                return true;
+            }
+            const declarationType = getTypeOfSymbol(declarationSymbol);
+            return type === declarationType || getTypeWithFacts(type, TypeFacts.NEUndefined) === getTypeWithFacts(declarationType, TypeFacts.NEUndefined);
+        }
+
         function typeNodeIsEquivalentToType(annotatedDeclaration: Node | undefined, type: Type, typeFromTypeNode: Type) {
             if (typeFromTypeNode === type) {
                 return true;
